/* Mock C: 70 original questions, reviewed against the supplied Bible. Held from topic practice until the form is taken. */
(function(root){'use strict';var add=root.L.addMC;
add("mock-c-001","ch13-nodes","An examiner completing the cervical lymph node examination moves on to the supraclavicular nodes. Where should the fingers be placed?",
["Along the anterior edge of the trapezius","Deep in the angle of the clavicle and SCM","Midline between the hyoid and manubrium","Midway between mandibular angle and tip"],1,
["The anterior edge of the trapezius is where posterior triangle nodes are palpated.","","The midline between the hyoid and manubrium is the anterior cervical node site.","Midway between the angle and tip of the mandible is the submandibular node site."],
"Supraclavicular nodes are palpated deep in the angle formed by the clavicle and the SCM muscle. The trapezius edge is for posterior triangle nodes.");
add("mock-c-002","ch13-nodes","A 20-year-old patient reports a painless lump in the midline of the neck that became swollen during a recent infection. Which cause is most suggested by its location?",
["Branchial cleft cyst","Virchow node","Thyroglossal duct cyst","Reactive submandibular node"],2,
["Branchial cleft cysts present as lateral, not midline, neck masses.","Virchow node is a left supraclavicular node, not a midline mass.","","Enlarged nodes such as submandibular nodes are lateral masses below the jaw."],
"Midline masses suggest a thyroglossal duct cyst, a developmental remnant that may become infected. Branchial cleft cysts and enlarged nodes are lateral.");
add("mock-c-003","ch13-thyroid","Standing behind a seated patient whose neck is slightly flexed, the examiner prepares to feel the thyroid isthmus rise as the patient swallows. Where should the index fingers rest?",
["Just above the thyroid cartilage notch","On the mobile hyoid bone","Within the suprasternal notch","Just below the cricoid cartilage"],3,
["The thyroid cartilage notch is above the cricoid and the isthmus lies below the cricoid.","The hyoid lies just below the mandible, well above the thyroid isthmus.","The gland normally lies above the suprasternal notch, and one below it is retrosternal and often not palpable.",""],
"In the posterior approach, the index fingers rest just below the cricoid cartilage, where the isthmus crosses the second to fourth tracheal rings. The thyroid cartilage notch is a higher landmark used for orientation.");
add("mock-c-004","ch14-acuity","During ophthalmoscopy of a nearsighted patient, the retinal structures are blurred with the wheel at 0 diopters. How should the examiner adjust the focusing wheel?",
["Clockwise to the plus/green diopters","Counterclockwise to the plus/green diopters","Clockwise to the minus/red diopters","Counterclockwise to the minus/red diopters"],3,
["Clockwise rotation to plus/green diopters corrects for a hyperopic eye.","Plus/green diopters are reached by clockwise rotation and suit hyperopia, not myopia.","Minus/red diopters are reached by counterclockwise, not clockwise, rotation.",""],
"For a myopic patient, rotate the wheel counterclockwise to the minus/red diopters. Clockwise rotation to plus/green diopters is used for a hyperopic eye.");
add("mock-c-005","ch14-blur","A 74-year-old patient reports gradually worsening central vision. Funduscopic examination shows sharply defined deposits of cellular debris (drusen). Which condition is most likely?",
["Primary open-angle glaucoma","Macular degeneration","Cataract","Diabetic retinopathy"],1,
["POAG causes optic nerve pallor and cupping with field loss rather than drusen.","","A cataract is clouding of the lens, not deposits in the fundus.","Diabetic retinopathy damages retinal blood vessels from chronic high blood sugar, not drusen deposits."],
"Poor central vision in an older adult with drusen fits macular degeneration. POAG instead causes optic nerve damage with an increased cup-to-disc ratio.");
add("mock-c-006","ch14-cornea","A 29-year-old patient has a thin grayish-white arc just inside the edge of each cornea. Which follow-up is most appropriate based on this finding?",
["Evaluate for hyperlipoproteinemia","Evaluate copper transport for Wilson disease","Ask about chronic excessive sun exposure","Ask about a prior corneal injury"],0,
["","Wilson disease produces a golden to red-brown Kayser–Fleischer ring, not a grayish-white arc.","Sun damage causes pterygium, a triangular conjunctival thickening.","An old injury causes a corneal scar, a variable superficial opacity rather than a peripheral arc."],
"A grayish-white arc near the corneal edge is corneal arcus, and in a young adult it suggests possible hyperlipoproteinemia. A Kayser–Fleischer ring is also peripheral but is golden to red-brown.");
add("mock-c-007","ch14-near","A patient has a unilaterally large pupil that reacts poorly to light. Which accompanying finding would point to oculomotor nerve (CN III) paralysis rather than a tonic (Adie) pupil?",
["Slow tonic constriction during near effort","Ipsilateral anhidrosis with ptosis","Ptosis with the eye deviated down and out","Blurred near vision from slow accommodation"],2,
["Slow tonic constriction during near vision is the hallmark of a tonic pupil.","Anhidrosis with ptosis is Horner syndrome, which causes a small, not large, pupil.","","Slow accommodation with blurred vision is a feature of a tonic pupil."],
"CN III paralysis gives a large, fixed pupil plus ptosis and a down-and-out eye. A tonic pupil is also large but shows slow tonic constriction on near effort without these motor signs.");
add("mock-c-008","ch14-redpain","When inspecting a red eye, which pattern of redness indicates conjunctival injection rather than ciliary injection?",
["Diffuse redness maximal toward the periphery","Redness concentrated around the limbus","Reddish-violet flush radiating from limbus","Homogeneous, sharply demarcated red area"],0,
["","Redness concentrated around the limbus is the ciliary injection of acute iritis.","A reddish-violet flush from deeper limbal vessels is ciliary injection, as in corneal injury.","A homogeneous, sharply demarcated area is leaked blood from subconjunctival hemorrhage."],
"Conjunctival injection is diffuse vessel dilatation with redness maximal peripherally. Ciliary injection involves deeper vessels and concentrates at the limbus.");
add("mock-c-009","ch15-hearing","A 24-year-old has decreased hearing in the left ear, and otoscopy shows a perforated left tympanic membrane; the right ear is normal. Which tuning fork results are expected?",
["Weber to the right; left Rinne bone equal to or longer than air","Weber to the left; left Rinne air longer than bone","Weber to the left; left Rinne bone equal to or longer than air","Weber to the right; left Rinne air longer than bone"],2,
["In conductive loss the Weber lateralizes to the impaired ear, which is the left, not the right.","Air longer than bone is the normal or sensorineural pattern; a perforated eardrum causes conductive loss with bone equal to or longer than air.","","This combination describes left sensorineural loss, not the conductive loss caused by a perforated eardrum."],
"A perforated eardrum causes conductive loss, so the Weber lateralizes to the impaired left ear and the left Rinne shows bone conduction equal to or longer than air conduction. Weber to the right with air longer than bone would instead indicate left sensorineural loss.");
add("mock-c-010","ch15-nose","Nasal examination shows a perforation with ulceration of the nasal septum. Which history item most directly explains this finding?",
["Aspirin sensitivity","Intranasal cocaine use","Cystic fibrosis","Allergic rhinitis"],1,
["Aspirin sensitivity is associated with nasal polyps, not septal perforation.","","Cystic fibrosis is associated with nasal polyps, not septal perforation.","Allergic rhinitis causes pale, bluish, or red mucosa and polyps, not septal perforation."],
"Intranasal cocaine or amphetamines cause septal perforation and ulceration, along with trauma, surgery, and granulomatosis with polyangiitis. Aspirin sensitivity, cystic fibrosis, and allergic rhinitis are associated with nasal polyps instead.");
add("mock-c-011","ch15-tinnitus","A 74-year-old reports ringing in both ears that began gradually several years ago. Which cause do the bilateral, chronic features most support?",
["Vestibular schwannoma","Meniere disease","Vascular tumor","Age-related hearing loss"],3,
["Vestibular schwannoma is listed among causes of unilateral tinnitus.","Meniere disease is listed among causes of unilateral tinnitus.","A vascular tumor is listed among causes of unilateral tinnitus.",""],
"Bilateral tinnitus points to age-related hearing loss or ototoxic medication exposure, and chronic onset also fits age-related loss. Vestibular schwannoma, Meniere disease, and vascular tumors are causes of unilateral tinnitus.");
add("mock-c-012","ch15-vertigo","A patient has sudden, persistent vertigo with nausea, vomiting, and nystagmus that has lasted several days. It is not triggered by head position, hearing is normal, there is no tinnitus, and there are no other neurologic deficits. Which cause fits best?",
["Vestibular neuronitis","Benign positional vertigo","Acute labyrinthitis","Acoustic neuroma"],0,
["","Benign positional vertigo produces episodes lasting seconds to under a minute, often triggered by rolling over or tilting the head.","Acute labyrinthitis has a similar course but causes unilateral sensorineural hearing loss.","Acoustic neuroma has insidious onset with one-sided hearing impairment and tinnitus."],
"Sudden vertigo lasting hours to days with nausea, vomiting, and nystagmus, but with normal hearing and no tinnitus, fits vestibular neuronitis. Acute labyrinthitis shares the time course but adds unilateral sensorineural hearing loss.");
add("mock-c-013","ch16-oral","A 22-year-old patient has smooth erosion of the lingual surfaces of the upper front teeth, exposing yellow-brown dentin. The biting edges have normal contours, and the teeth are normally sized and spaced. Which history best explains this pattern?",
["Many decades of chewing wear","Opening bobby pins with the teeth","Recurrent vomiting from bulimia","Untreated congenital syphilis"],2,
["Attrition from years of chewing wears down the chewing surfaces in older adults, not the lingual surfaces of a young patient's front teeth.","Recurrent trauma such as opening bobby pins abrades or notches the biting surface, which is normal here.","","Hutchinson teeth of congenital syphilis are smaller, widely spaced, and notched on their biting surfaces."],
"Table 16-3 describes severe erosion of the lingual surfaces of the maxillary teeth, exposing yellow-brown dentin, as the result of recurrent regurgitation of stomach contents, as in bulimia or severe acid reflux. Attrition and abrasion damage the chewing or biting surfaces instead, and Hutchinson teeth are small, widely spaced, and notched.");
add("mock-c-014","ch16-oral","A healthy adult has a few small, asymptomatic yellowish spots on the buccal mucosa and lips. Which is the most appropriate interpretation?",
["Fordyce spots, normal sebaceous glands","Koplik spots, an early sign of measles","Leukoplakia, a lesion requiring biopsy","Petechiae from decreased platelets"],0,
["","Koplik spots are white salt-grain specks on a red background near the molars, not yellowish spots.","Leukoplakia is a thickened white patch rather than small yellowish spots.","Petechiae are small red spots from blood escaping capillaries, not yellowish spots."],
"Fordyce spots are normal sebaceous glands that appear as small yellowish spots on the buccal mucosa or lips, so no workup is needed. Koplik spots are white rather than yellow and appear near the molars in early measles.");
add("mock-c-015","ch17-advent","A patient with acute pneumonia has loud, low-pitched, popping crackles that begin in early inspiration and last through expiration. Which other feature is expected of this type of crackle?",
["They vary with body position","They are more frequent per breath than fine crackles","They change or disappear with coughing","They are shorter in duration than fine crackles"],2,
["Fine crackles change with body position; coarse crackles do not vary with position.","Fine crackles are the more frequent per breath; coarse crackles are fewer.","","Coarse crackles have a longer duration than fine crackles, not a shorter one."],
"These are coarse crackles, which are biphasic, popping, lower in frequency, longer in duration, do not vary with body position, and change or disappear with coughing. Positional change is a feature of fine crackles, the most tempting mix-up.");
add("mock-c-016","ch17-advent","A patient has a wheeze that is heard persistently over one small area of the right lung rather than throughout both lungs. Which cause should the examiner consider?",
["Asthma","Pulmonary fibrosis","Pleurisy","Foreign body"],3,
["Asthma is the typical cause of wheezes, but a persistently localized wheeze points to focal obstruction.","Pulmonary fibrosis is associated with crackles rather than a localized wheeze.","Pleurisy is associated with a pleural friction rub rather than a wheeze.",""],
"Wheezes may be localized because of a foreign body, mucous plug, or tumor, or heard throughout the lung. A single fixed focus of wheezing therefore suggests focal airway obstruction such as a foreign body.");
add("mock-c-017","ch17-breath","The examiner hears very loud breath sounds in which the inspiratory and expiratory phases are almost equal and continue without any pause. Which normal breath sound is this?",
["Tracheal","Bronchovesicular","Bronchial","Vesicular"],0,
["","Bronchovesicular sounds also have nearly equal phases but are intermediate in intensity and at times separated by a silent interval.","Bronchial sounds have a longer expiratory phase and a short silence between phases.","Vesicular sounds are soft, with inspiration longer than expiration."],
"Tracheal breath sounds are very loud, with nearly equal phases that are continuous without pause, and are heard over the trachea in the neck. Bronchovesicular sounds share equal phases but are only intermediate in intensity and may have a silent gap.");
add("mock-c-018","ch17-chestdis","A patient has a known left pneumothorax. Which finding from Table 17-8 specifically indicates that it has become a tension pneumothorax?",
["Tympany over the left chest","Trachea shifted toward the right","Absent breath sounds on the left","Trachea shifted toward the left"],1,
["A hyper-resonant or tympanitic note occurs over pleural air in any pneumothorax.","","Decreased to absent breath sounds occur over pleural air in any pneumothorax.","A trachea shifted toward the involved side is the pattern of atelectasis, not pneumothorax."],
"In Table 17-8, the trachea shifts toward the unaffected side only if the pneumothorax is under tension; with a left pneumothorax that means a shift to the right. Tympany and absent breath sounds occur with any pneumothorax.");
add("mock-c-019","ch17-chestdis","A patient with fever has dullness to percussion at the right lung base. Which finding over the lowest part of the dull area would favor pleural effusion rather than lobar pneumonia?",
["Bronchial breath sounds","Egophony and bronchophony","Late inspiratory crackles","Decreased tactile fremitus"],3,
["Bronchial breath sounds over the involved area favor lobar pneumonia; over the fluid of an effusion, breath sounds are decreased to absent.","Increased transmitted voice sounds such as egophony and bronchophony favor consolidation.","Late inspiratory crackles over the involved area favor lobar pneumonia; effusion has none except a possible rub.",""],
"Both conditions are dull, but pleural effusion decreases or abolishes fremitus and transmitted voice sounds over the fluid, whereas lobar pneumonia increases them along with bronchial breath sounds and late inspiratory crackles.");
add("mock-c-020","ch17-chestdis","A patient with a large right pleural effusion has flat percussion and absent breath sounds at the base. Near the upper edge of the fluid, the examiner hears bronchial breath sounds. What is the best interpretation?",
["Expected finding near the top of a large effusion","Sign of a coexisting tension pneumothorax","Sign of right upper lobe atelectasis","Sign of hyperinflation above the fluid"],0,
["","Tension pneumothorax produces hyper-resonance with decreased to absent breath sounds, not bronchial sounds.","Right upper lobe atelectasis can transmit tracheal sounds, but bronchial sounds at the upper margin of a large effusion are already expected.","Hyperinflation, as in COPD, decreases breath sounds rather than producing bronchial sounds."],
"Table 17-8 notes that bronchial breath sounds may be heard near the top of a large effusion even though breath sounds over the fluid are decreased to absent. No second process is needed to explain them.");
add("mock-c-021","ch17-cough","A patient reports a dry cough that worsens with exertion and at night, along with orthopnea and paroxysmal nocturnal dyspnea. Recently the sputum has become pink and frothy. Which problem is most likely?",
["Pulmonary embolism","Left ventricular failure","Gastroesophageal reflux","Asthma"],1,
["Pulmonary embolism causes a dry cough with possible hemoptysis, pleuritic pain, and tachypnea, not orthopnea with pink frothy sputum.","","Gastroesophageal reflux causes nocturnal cough with heartburn, regurgitation, and early morning hoarseness.","Asthma causes episodic wheezing, with thick mucoid sputum near the end of an attack."],
"Left ventricular failure causes a cough that is often dry on exertion or at night, with orthopnea and paroxysmal nocturnal dyspnea, and can progress to the pink frothy sputum of pulmonary edema. Reflux also worsens at night but lacks orthopnea and frothy sputum.");
add("mock-c-022","ch17-distress","A patient with severe systemic acidosis has deep, rapid respirations. Which term best describes this breathing pattern?",
["Cheyne-Stokes breathing","Obstructive breathing","Ataxic (Biot) breathing","Kussmaul breathing"],3,
["Cheyne-Stokes breathing alternates periods of deep breathing with apnea.","Obstructive breathing features prolonged expiration from narrowed airways.","Ataxic breathing is irregular with periods of apnea and is linked to medullary injury.",""],
"Kussmaul breathing is compensatory overbreathing due to systemic acidosis. Cheyne-Stokes breathing also includes deep breaths but alternates them with apnea.");
add("mock-c-023","ch17-percussion","A student places only the distal interphalangeal joint of the pleximeter finger on the chest and strikes it with the fingertip using a wrist motion, but leaves the plexor finger resting on the joint after each strike. Which correction will improve the note?",
["Strike with the finger pad instead of the tip","Press the whole palm against the chest wall","Withdraw the striking finger quickly","Move the strike from the elbow instead of the wrist"],2,
["The strike should use the tip of the plexor finger, not the pad.","Only the distal interphalangeal joint should contact the chest; more contact dampens vibrations.","","The percussion movement should originate at the wrist, not the elbow."],
"Leaving the plexor finger on the pleximeter damps the vibrations, so the striking finger should be withdrawn quickly. The other changes would undo parts of the technique the student is already doing correctly.");
add("mock-c-024","ch18-cvrisk","During cardiovascular risk counseling, a patient asks which modifiable risk factor accounts for the most atherosclerotic cardiovascular deaths. Which answer does the chapter support?",
["Tobacco use","Dyslipidemia","Physical inactivity","Hypertension"],3,
["Tobacco use is modifiable, but the chapter names hypertension as the leading contributor to atherosclerotic deaths.","Dyslipidemia is modifiable, but the chapter names hypertension as the leading contributor to atherosclerotic deaths.","Physical inactivity is modifiable, but the chapter names hypertension as the leading contributor to atherosclerotic deaths.",""],
"The chapter states that hypertension accounts for more atherosclerotic cardiovascular deaths than any other modifiable risk factor. Tobacco use, dyslipidemia, and inactivity are also modifiable but are not singled out this way.");
add("mock-c-025","ch18-cycle","A 68-year-old with long-standing hypertension and a stiff, less compliant left ventricle has a dull, low-pitched extra sound just before S1. Which phase of the cardiac cycle produces this sound?",
["Rapid ventricular filling","Isovolumetric contraction","Isovolumetric relaxation","Atrial contraction"],3,
["Rapid ventricular filling in early diastole is associated with S3, not a sound just before S1.","Isovolumetric contraction follows S1, after the mitral valve has closed.","Isovolumetric relaxation occurs just after S2, at the start of diastole.",""],
"The atrial kick at the end of diastole can contribute to S4, especially when ventricular compliance is decreased. Rapid ventricular filling earlier in diastole is the phase associated with S3.");
add("mock-c-026","ch18-grade","A systolic murmur is very loud and accompanied by a thrill. It can still be heard when the stethoscope is tilted partly off the chest, but not when it is lifted entirely off. Which grade fits?",
["Grade 3/6","Grade 4/6","Grade 5/6","Grade 6/6"],2,
["Grade 3/6 is louder than S1 and S2 but has no thrill.","Grade 4/6 is loud with a thrill but is not described as audible with the stethoscope partly off the chest.","","Grade 6/6 can be heard with the stethoscope entirely off the chest."],
"Grade 5/6 is very loud with a thrill and may be heard with the stethoscope partly off the chest. Grade 6/6 is reserved for a murmur audible with the stethoscope entirely off the chest.");
add("mock-c-027","ch18-jvp","A patient with suspected heart failure is positioned with the head of the bed at 30 degrees. Internal jugular pulsations are seen, but their highest point is above the angle of the jaw and cannot be measured. What should the examiner do next?",
["Raise the head of the bed until the top is visible","Lower the head of the bed toward 0 degrees","Press lightly above the sternal end of the clavicle","Turn the head sharply toward the side examined"],0,
["","Lowering the bed is used when the JVP is expected to be low; here it would move the top even higher.","Light pressure above the clavicle eliminates jugular pulsations; it distinguishes them from carotid pulsations but does not measure height.","The head should be turned slightly away from the side being inspected."],
"When the JVP is high, the oscillation point may be above the jaw at 30 degrees; raising the head of the bed (for example, to 60 degrees) brings the top into view. The height above the sternal angle stays similar, so the measurement remains valid.");
add("mock-c-028","ch18-maneuvers","A 19-year-old college student has a soft grade 2/6 midsystolic murmur at the left third interspace near the sternum. S2 splits normally, there are no ejection sounds or extra sounds, and the murmur fades when she sits up. Which is most likely?",
["Aortic stenosis","Hypertrophic cardiomyopathy","Innocent murmur","Pulmonic stenosis"],2,
["The aortic stenosis murmur is at the right second and third interspaces and is heard best with the patient sitting and leaning forward.","Hypertrophic cardiomyopathy usually has an apical S4 and a sustained apical impulse, and its murmur increases rather than fades when left ventricular volume falls.","","Pulmonic stenosis typically has an early pulmonic ejection sound and, if severe, a widely split S2."],
"An innocent murmur is a soft grade 1 to 2 midsystolic murmur at the left second to fourth interspaces with no associated findings, and it usually decreases or disappears on sitting. Aortic stenosis, by contrast, is heard best with the patient sitting and leaning forward.");
add("mock-c-029","ch18-metabolic","A 44-year-old with no known cardiovascular disease has elevated blood pressure, elevated fasting glucose, and elevated triglycerides. Which USPSTF recommendation applies to behavioral counseling on diet and physical activity?",
["Offer or refer for behavioral counseling (grade B)","Individualize the counseling decision (grade C)","Evidence is insufficient to recommend (I statement)","Strongly recommend for all adults (grade A)"],0,
["","Individualized decisions (grade C) apply to adults without CVD risk factors.","The I statement in the chapter applies to statins in adults 76 and older, not to this counseling.","The grade A recommendation in this section is for tobacco cessation interventions, not diet and activity counseling."],
"Three of five criteria establish metabolic syndrome, which places this patient in the USPSTF target population for grade B behavioral counseling on healthy diet and physical activity. The grade C individualized approach is reserved for adults without CVD risk factors.");
add("mock-c-030","ch18-murmurtiming","A 30-year-old has a high-pitched click in mid-systole heard best just medial to the apex, followed by a murmur that persists up to S2. Which condition does this pattern most suggest?",
["Aortic stenosis","Ventricular septal defect","Pulmonic stenosis","Mitral valve prolapse"],3,
["Aortic stenosis produces a midsystolic murmur at the right second interspace that stops before S2.","A VSD murmur is holosystolic, starting with S1 rather than after a mid-systolic click.","Pulmonic stenosis has an early ejection sound just after S1, not a mid-systolic click, and is loudest at the left second and third interspaces.",""],
"A late systolic murmur starts in mid- or late systole and persists up to S2; it is the murmur of mitral valve prolapse and is often preceded by a systolic click. A VSD murmur also reaches S2 but begins with S1.");
add("mock-c-031","ch18-pmi","A patient in the third trimester of pregnancy has a brisk, nonsustained apical impulse under 2.5 cm in diameter. It is located in the fourth intercostal space, higher and slightly more to the left than usual. Which interpretation is most appropriate?",
["Left ventricular hypertrophy","Upward shift related to pregnancy","Right ventricular hypertrophy","Dextrocardia"],1,
["Left ventricular enlargement produces a diffuse impulse, usually over 3 cm, rather than a small brisk tap.","","Right ventricular hypertrophy may make the xiphoid or epigastric impulse most prominent.","Dextrocardia positions the PMI on the right side of the chest."],
"Box 18-17 notes that pregnancy or a high left diaphragm can shift the apical impulse upward and to the left. The normal size and brisk, nonsustained quality argue against left ventricular enlargement.");
add("mock-c-032","ch18-s1s2","In a healthy 22-year-old, S2 sounds single at the apex even during a deep breath in. Where should the examiner listen to assess for physiologic splitting of S2?",
["Apex with the patient in left lateral decubitus","Lower left sternal border","Second or third left interspace","Right second interspace"],2,
["S2 typically sounds single at the apex because P2 is too soft to hear there.","The lower left sternal border is where splitting of S1 is detected.","","At the aortic area S2 typically sounds single, reflecting aortic valve closure."],
"Splitting of S2 should be assessed in the second or third left intercostal space, where the soft P2 is audible. At the apex or aortic area, S2 normally sounds single because the pulmonic component is too soft to detect.");
add("mock-c-033","ch18-systdiast","A 52-year-old with a history of rheumatic fever has a low-pitched rumbling diastolic murmur with presystolic accentuation, heard with the bell. S1 is loud, and a snapping sound follows S2 and initiates the murmur. Which lesion is most likely?",
["Aortic regurgitation","Mitral stenosis","Tricuspid regurgitation","Mitral regurgitation"],1,
["Aortic regurgitation is a high-pitched blowing decrescendo murmur heard with the diaphragm.","","Tricuspid regurgitation is a holosystolic murmur at the lower left sternal border.","Mitral regurgitation is a holosystolic apical murmur radiating to the axilla, not a diastolic rumble."],
"Rumbling mid- or late diastolic murmurs point to stenosis of an AV valve, usually the mitral; a loud S1 and an opening snap that initiates the murmur complete the picture of mitral stenosis. Aortic regurgitation is also diastolic but is high pitched and blowing.");
add("mock-c-034","ch18-valves","An examiner wants to listen over the chest wall location where mitral valve sounds and murmurs typically originate. Where should the stethoscope be placed?",
["Left fifth interspace at the midclavicular line","Left fourth interspace at the lower sternal border","Right second interspace near the sternum","Left second and third interspaces near the sternum"],0,
["","The left fourth interspace at the lower left sternal border is the tricuspid area.","The right second interspace is the aortic area.","The left second and third interspaces near the sternum are the pulmonic area."],
"Box 18-2 places mitral valve sounds at the left fifth intercostal space at the midclavicular line, at and around the cardiac apex. The lower left sternal border at the fourth interspace is the neighboring tricuspid area.");
add("mock-c-035","ch19-abi","To measure ankle pressure for an ABI, the cuff above the malleoli is inflated to 20 mm Hg above the last audible Doppler pulse. At what point is the ankle systolic pressure recorded?",
["When the Doppler signal first disappears during inflation","At the peak cuff pressure reached during inflation","When the dorsalis pedis pulse becomes palpable again","When the Doppler signal becomes audible again on slow deflation"],3,
["The pressure is recorded during slow deflation, not at the point the signal is lost on inflation.","Peak pressure is set 20 mm Hg above the last audible pulse, so it overestimates the systolic pressure.","The ABI technique relies on the Doppler signal, not a palpable pulse.",""],
"For each ankle artery, the cuff is deflated slowly (about 1 mm Hg per second) and the pressure is recorded when the Doppler pulse becomes audible again. Recording at peak cuff pressure would overestimate the value by design.");
add("mock-c-036","ch19-arteryvein","A patient with advanced chronic arterial insufficiency has rest pain and now sleeps with the affected leg hanging over the edge of the bed. Mild ankle edema has appeared on that side only. What best explains the edema?",
["Venous stasis and hypertension from incompetent valves","Lymphatic obstruction with protein-rich fluid","Prolonged dependent positioning of the leg","Sodium retention from heart failure"],2,
["Venous stasis edema is present and often marked in chronic venous insufficiency, not a new mild edema tied to dependency of an ischemic limb.","Lymphedema becomes hard and nonpitting and is not explained by keeping an ischemic leg dependent.","","Edema from heart failure is bilateral, not limited to one leg."],
"Table 19-3 notes that edema in arterial insufficiency is absent or mild but may develop as the patient tries to relieve rest pain by lowering the leg, so the unilateral edema reflects prolonged dependency. Venous insufficiency, the closest competitor, produces edema that is present and often marked.");
add("mock-c-037","ch19-claud","A patient reports cramping calf pain with walking that resolves within a few minutes of rest. Which additional history response would most increase the likelihood that PAD is the cause?",
["Pain that is sharp or stabbing in quality","Swelling of both ankles by evening","Relief that comes only from bending forward","A long history of cigarette smoking"],3,
["Sharp or stabbing pain may suggest underlying spinal stenosis rather than PAD.","Leg or ankle swelling may suggest venous insufficiency or DVT.","Relief that comes only from bending forward or sitting points to neurogenic claudication from spinal stenosis.",""],
"Box 19-6 lists smoking or a history of vascular disease as risk factors that increase the likelihood of underlying PAD. Sharp pain and relief by bending forward point toward spinal stenosis, and swelling points toward a venous cause.");
add("mock-c-038","ch19-pad","A patient's examination shows bilateral femoral bruits and no abdominal bruits. Brachial and radial pulses are 2+, while femoral, popliteal, DP, and PT pulses are 1+. Where do these findings best localize the arterial compromise?",
["Peripheral arteries of the lower extremities","Abdominal aorta","Renal arteries","Arteries of the upper extremities"],0,
["","The absence of abdominal bruits argues against the abdominal aorta as the site.","The absence of abdominal bruits argues against the renal arteries as the site.","Brachial and radial pulses are a normal 2+, so the upper extremity arteries are not implicated."],
"Femoral bruits indicate turbulent flow from narrowing, and the absence of abdominal bruits helps localize the compromise to the peripheral arteries rather than the aorta or renal arteries. Normal arm pulses with diminished leg pulses further support lower extremity PAD.");
add("mock-c-039","ch19-pulses","In a healthy 30-year-old, both posterior tibial pulses are 2+, but the examiner cannot feel the left dorsalis pedis pulse just lateral to the extensor tendon of the great toe. What is the best next step?",
["Record the absent pulse as evidence of PAD","Explore the dorsum of the foot more laterally","Move the fingers up onto the front of the ankle","Palpate behind the medial malleolus instead"],1,
["The DP artery may be congenitally absent or branch higher, so a missing DP pulse alone is not proof of PAD.","","The DP pulse is palpated on the dorsum of the foot, not the ankle.","Behind the medial malleolus is the posterior tibial pulse, which has already been found."],
"The DP artery may be congenitally absent or branch higher in the ankle, so when it cannot be felt the examiner should explore the dorsum of the foot more laterally. Labeling it PAD in a young patient with normal PT pulses would be premature.");
add("mock-c-040","ch19-pvexam","An examiner performing a peripheral vascular examination has finished the carotid arteries and the upper extremities. Following the recommended top-down sequence, which step comes next?",
["Palpating the femoral pulses below the inguinal ligament","Palpating the epitrochlear nodes at the elbow","Palpating the abdominal aorta for a pulsatile mass","Palpating the calves for venous tenderness or cords"],2,
["The femoral pulses belong to the lower extremity portion, which comes after the abdomen.","The epitrochlear nodes are part of the upper extremity portion, which is already finished.","","Palpating the calves for venous tenderness is part of the final lower extremity portion."],
"The examination proceeds from the carotid arteries to the upper extremities, then the abdomen, and finally the lower extremities. In the abdomen, the examiner palpates the aorta, because a pulsatile mass may be an AAA.");
add("mock-c-041","ch19-ulcers","An ulcer lies over the lateral malleolus. Which set of associated findings would most support chronic venous insufficiency as its cause?",
["Edema, varicosities, and stasis dermatitis","Callus, decreased sensation, and absent ankle jerks","Decreased pulses, foot pallor, and dependent rubor","Atrophic skin, no callus, and gangrene of a toe"],0,
["","Callus, decreased sensation, and absent ankle jerks point to a neuropathic ulcer.","Decreased pulses, pallor on elevation, and dusky rubor on dependency point to an arterial ulcer.","Atrophic skin without callus and gangrene point to an arterial ulcer."],
"Venous ulcers usually occur over the medial and sometimes the lateral malleolus, with associated edema, pigmentation and purpura, varicosities, and stasis dermatitis. The other sets describe neuropathic or arterial ulcers.");
add("mock-c-042","ch21-acute","After a large fatty dinner, a patient develops epigastric and right upper quadrant pain that builds over a few minutes, radiates to the right scapula, lasts about 2 hours, and then gradually subsides. Similar episodes have occurred before. Which diagnosis is most likely?",
["Biliary colic","Acute cholecystitis","Peptic ulcer","Acute pancreatitis"],0,
["","Acute cholecystitis has gradual onset with steady, persistent pain lasting longer than biliary colic, plus fever.","Peptic ulcer pain is gnawing or burning, may radiate straight to the back, and may be relieved by food.","Acute pancreatitis is persistent, severe epigastric pain radiating straight to the back."],
"Rapid onset after a fatty meal, radiation to the right scapula, and gradual subsidence within hours with recurrence fit biliary colic. Acute cholecystitis shares the location but is steady and persistent with a longer course.");
add("mock-c-043","ch21-acute","A patient with prior abdominal surgery has cramping, colicky generalized abdominal pain, vomiting, and progressive distention and has not passed flatus or stool. Which diagnosis is most likely?",
["Acute diverticulitis","Mesenteric ischemia","Acute bowel obstruction","Chronic pancreatitis"],2,
["Acute diverticulitis causes left lower quadrant or pelvic pain with fever and diarrhea.","Mesenteric ischemia is marked by pain out of proportion to examination, bloody stool, and shock.","","Chronic pancreatitis causes epigastric pain radiating to the back with steatorrhea."],
"Colicky generalized pain from distention with vomiting and no passage of flatus or stool fits acute bowel obstruction, often from adhesions after surgery. Mesenteric ischemia can cause vomiting and distention but is defined by pain out of proportion to the examination.");
add("mock-c-044","ch21-aorta","A 67-year-old man who smokes has his aorta assessed by deep palpation with one hand on each side. The width is estimated at 2.5 cm, excluding the abdominal wall. How should this be interpreted?",
["Consistent with an abdominal aortic aneurysm","Suggests aortoiliac occlusive disease","Within normal width for his age group","Suggests renal artery stenosis"],2,
["An aneurysm is suggested by an expansile mass 3 cm or more in diameter.","Aortoiliac occlusive disease is suggested by bruits, not by a normal palpated width.","","Renal artery stenosis is suggested by bruits above and lateral to the umbilicus, not by aortic width."],
"In adults older than 50, a normal aorta is not more than 3 cm wide, with an average of 2.5 cm. A width of 3 cm or more with expansile pulsation would instead suggest an aneurysm.");
add("mock-c-045","ch21-hepatomeg","To locate the lower border of liver dullness in the right midclavicular line, where should percussion begin?",
["At the nipple line, percussing downward","Below the umbilicus in tympany, percussing upward","At the right costal margin, percussing downward","At the xiphoid process, percussing laterally"],1,
["Starting at the nipple line and percussing downward locates the upper border of liver dullness.","","Starting at the costal margin risks beginning over the liver and missing the lower border of an enlarged liver.","Liver span is measured vertically in the midclavicular line, not by lateral percussion from the xiphoid."],
"The lower border is found by starting well below the umbilicus in an area of tympany and percussing upward toward the liver. Percussing downward from the nipple line is how the upper border is found.");
add("mock-c-046","ch21-sequence","The examiner percusses the lowest interspace in the left anterior axillary line and hears tympany. When the patient takes a deep breath, the note changes to dullness. What does this finding suggest?",
["Normal spleen size","Normal gastric air bubble","Normal liver dullness","Possible splenomegaly"],3,
["With a normal spleen the note usually stays tympanitic on deep inspiration.","The gastric air bubble produces tympany, not dullness that appears with inspiration.","Liver dullness is found on the right, not in the left anterior axillary line.",""],
"A change from tympany to dullness on inspiration is a positive splenic percussion sign suggesting splenomegaly, though it is only moderately useful. A normal-sized spleen leaves the note tympanitic.");
add("mock-c-047","ch21-special","An examiner is palpating for the classic point of tenderness in acute appendicitis. Where is McBurney point located?",
["2 inches below the umbilicus in the midline","2 inches from the ASIS toward the umbilicus","Just above the right inguinal ligament","Below the right costal margin at the midclavicular line"],1,
["The midline below the umbilicus is the hypogastric region, not McBurney point.","","Tenderness just above the inguinal ligaments is typical of acute salpingitis.","Below the right costal margin is where the gallbladder is palpated for the Murphy sign."],
"McBurney point lies 2 inches from the anterior superior iliac spine on a line to the umbilicus. Tenderness just above the inguinal ligaments is the pattern described for salpingitis, not appendicitis.");
add("mock-c-048","ch21-special","A patient has right upper quadrant pain suspicious for acute cholecystitis, but routine palpation of the right upper quadrant produces no tenderness. Which maneuver should the examiner perform next?",
["Deep left lower quadrant pressure followed by quick withdrawal","Flexion and internal rotation of the right hip","Fist percussion over the right costovertebral angle","Deep right upper quadrant palpation while the patient inhales deeply"],3,
["Left lower quadrant pressure with quick withdrawal tests the Rovsing sign for appendicitis.","Flexion and internal rotation of the right hip tests the obturator sign for a pelvic appendix.","Costovertebral angle fist percussion assesses for pyelonephritis or renal colic.",""],
"When cholecystitis is suspected but the right upper quadrant is not tender, test the Murphy sign by palpating deeply while the patient takes a deep breath. The other maneuvers assess the appendix or kidney.");
add("mock-c-049","ch21-tips","A frightened, ticklish patient tenses each time the examiner begins abdominal palpation. Which approach is recommended?",
["Begin palpation with the patient's hand under yours","Ask the patient to raise both arms above the head","Start with deep palpation to finish quickly","Palpate any painful area first to reassure"],0,
["","Arms above the head stretch and tighten the abdominal wall, hindering palpation.","Quick, unexpected, deep palpation increases tension; a calm, gradual approach is advised.","Painful areas should be examined last, not first."],
"For a frightened or ticklish patient, begin palpation with the patient's hand under yours, then slip your hand underneath after a few moments. Raising the arms would tighten the abdominal wall instead of relaxing it.");
add("mock-c-050","ch27-clonus","Minutes after a generalized tonic-clonic seizure, stroking the lateral sole produces dorsiflexion of the big toe with fanning of the other toes. The next day the big toe plantar flexes normally. Which interpretation fits best?",
["Normal plantar response","Withdrawal response to the stimulus","Transient Babinski response after a seizure","Permanent corticospinal tract lesion"],2,
["The normal plantar response is plantar flexion of the big toe, not dorsiflexion with fanning.","Withdrawal is flexion of the hip and knee, not big toe dorsiflexion with fanning.","","The response resolved by the next day, which fits a transient postictal finding."],
"The Babinski response can be transiently positive during the postictal period after a seizure or in unconscious states from intoxication. Its resolution the next day argues against a fixed corticospinal lesion.");
add("mock-c-051","ch27-cns-pns","After a fall, a patient has weakness and spasticity of both legs with brisk knee and ankle reflexes. Sensation is lost on both sides below a band across the trunk at the level of the umbilicus. Which lesion location is most likely?",
["Cerebral cortex","Spinal cord","Spinal roots and nerves","Basal ganglia"],1,
["A cortical lesion causes one-sided weakness with contralateral sensory loss in the face, limbs, and trunk, not a bilateral trunk level.","","Root lesions decrease reflexes and cause sensory loss limited to a dermatome.","Basal ganglia disease causes bradykinesia, rigidity, and tremor with sensation not affected."],
"Table 27-1 describes spinal cord lesions as bilateral weakness and spasticity with increased reflexes and a dermatomal sensory level on the trunk with loss below it. Root lesions would reduce reflexes.");
add("mock-c-052","ch27-coma-pupils","In a comatose patient without neck injury, the examiner turns the head to the right. The eyes stay fixed straight ahead and move with the head instead of toward the left. Which interpretation fits?",
["Suspicious for a midbrain or pons lesion","Normal doll's eye response, intact brainstem","Eyes looking toward a hemispheric lesion","Isolated lesion of the facial nerve (CN VII)"],0,
["","With an intact brainstem, the eyes would move toward the opposite side (left) as the head turns right.","A hemispheric lesion causes a gaze deviation toward the lesion, not loss of eye movement with head turning.","CN VII affects blinking on the weak side, not the oculocephalic reflex."],
"When doll's eye movements are absent, the eyes keep looking straight ahead with no movement relative to head position, which is suspicious for a midbrain or pons lesion. An intact reflex moves the eyes opposite to the head turn.");
add("mock-c-053","ch27-conscious","A comatose patient has both upper arms flexed tight to the sides with the elbows, wrists, and fingers flexed. The legs are extended and internally rotated with the feet plantar flexed. Where is the lesion most likely?",
["Diencephalon, midbrain, or pons","Cerebellar hemisphere and its related tracts","Peripheral nerves supplying the four limbs","Corticospinal tracts near the hemispheres"],3,
["That location causes decerebrate rigidity, with the arms extended and pronated rather than flexed.","Cerebellar lesions impair coordination and decrease tone; they are not the source of this flexor posture.","Peripheral nerve lesions cause flaccid weakness, not a stereotyped flexor posture in coma.",""],
"This is decorticate rigidity, which when bilateral in a comatose patient implies a destructive lesion of the corticospinal tracts within or very near the cerebral hemispheres. Decerebrate rigidity, with extended arms, points lower to the diencephalon, midbrain, or pons.");
add("mock-c-054","ch27-cranial","While testing the trigeminal nerve, the examiner notes that the jaw deviates to the right each time the patient opens the mouth. Which finding does this suggest?",
["Right trigeminal (CN V) motor weakness","Left trigeminal (CN V) motor weakness","Right facial nerve (CN VII) weakness","Right hypoglossal (CN XII) weakness"],0,
["","The jaw deviates toward the weak side, so rightward deviation points to the right.","CN VII controls facial expression, not the jaw muscles.","CN XII weakness causes the protruded tongue, not the jaw, to deviate."],
"Jaw deviation during opening points to weakness on the deviating side, so deviation to the right indicates right-sided CN V motor weakness. Confusing the direction leads to the left-sided choice.");
add("mock-c-055","ch27-headred","A patient with a long history of migraine comes in with a headache. Which finding on examination is a warning sign that calls for prompt investigation?",
["Papilledema on fundoscopic examination","Nausea with sensitivity to light","Unilateral throbbing pain like prior attacks","Relief after sleep in a dark, quiet room"],0,
["","Nausea and photophobia are common migraine features and are not listed warning signs.","Unilateral throbbing pain matching past attacks is typical migraine without a change in pattern.","Relief with sleep in a quiet, dark room is typical of migraine, not a warning sign."],
"Box 27-5 lists associated papilledema, neck stiffness, or focal neurologic deficits as headache warning signs. The other options are familiar migraine features that do not change the pattern.");
add("mock-c-056","ch27-headtypes","A patient reports a steady, dull, aching headache that is worse on awakening and improves over several hours. Over the past weeks there has also been a new seizure and a change in personality. Which cause is most likely?",
["Meningitis","Subarachnoid hemorrhage","Postconcussion headache","Brain tumor"],3,
["Meningitis causes a generalized, very severe headache with fever, stiff neck, and photophobia.","Subarachnoid hemorrhage causes a sudden, very severe \"worst\" headache, not a pattern worse on waking.","Postconcussion headache follows a head injury and tends to diminish over time.",""],
"Table 27-5 describes the brain tumor headache as aching, steady, dull pain that is worse on awakening and improves after several hours, with associated seizures and personality changes. Subarachnoid hemorrhage presents instead with sudden, very severe pain.");
add("mock-c-057","ch27-nystagmus","A patient's nystagmus becomes more pronounced when asked to fix vision on a distant object. The patient also has slurred speech and an unsteady, uncoordinated gait. Which explanation best fits?",
["Vestibular disorder","Cerebellar disease","Normal response to a moving object","Normal beats at extreme lateral gaze"],1,
["Vestibular nystagmus decreases with retinal fixation rather than increasing.","","Normal nystagmus occurs while watching a rapidly moving object, not during fixation on a still target.","Normal end-gaze beats appear only at extreme lateral gaze and do not come with ataxia or dysarthria."],
"Nystagmus in cerebellar disease increases with retinal fixation and may be accompanied by ataxia and dysarthria. Vestibular nystagmus is the key contrast because it decreases with fixation.");
add("mock-c-058","ch27-reflex","A 22-year-old taking a serotonergic antidepressant has symmetric reflexes that are brisker than average. Sharp dorsiflexion of the ankle produces no rhythmic oscillation. Which grade best describes these reflexes?",
["Grade 4","Grade 2","Grade 1","Grade 3"],3,
["Grade 4 requires clonus, which is absent here.","Grade 2 is an average, normal response, not one brisker than average.","Grade 1 is somewhat diminished or needs reinforcement.",""],
"Grade 3 is brisker than average and possibly but not necessarily a sign of disease, and brisk reflexes can occur in young patients or with serotonergic drugs. Grade 4 requires clonus, which this patient lacks.");
add("mock-c-059","ch27-seizure","A patient has a tonic-clonic seizure. Afterward the patient recalls smelling a burning odor just before it began and has weakness of the right arm for several hours. Which classification do these features support?",
["Primary generalized tonic-clonic seizure","Atypical absence seizure","Focal seizure that became generalized","Nonepileptic seizure"],2,
["A primary tonic-clonic seizure leaves the patient amnestic for any aura, and persisting deficits are bilateral.","Absence seizures cause a brief lapse without falling and no aura is recalled.","","Nonepileptic seizures often do not follow a neuroanatomic pattern, unlike a one-sided postictal deficit."],
"Table 27-8 names two attributes of a partial seizure that has become generalized: recollection of an aura and a unilateral neurologic deficit after the seizure. After a primary tonic-clonic seizure the patient is amnestic for the aura and any deficits are bilateral.");
add("mock-c-060","ch28-child-face","While checking the red reflex with an ophthalmoscope, the examiner sees a white reflex in one of an infant's eyes. Which condition is a possible cause of this finding?",
["Congenital glaucoma","Retinoblastoma","Brushfield spots","Esotropia"],1,
["Congenital glaucoma is linked to corneal cloudiness rather than a white retinal reflex.","","Brushfield spots are a ring of white specks in the iris suggesting Down syndrome, not a change in the retinal reflex.","Esotropia is an inward eye deviation, a form of strabismus, not a change in the red reflex."],
"A white retinal reflex (leukokoria) is abnormal and may indicate cataract, retinal detachment, chorioretinitis, or retinoblastoma. Congenital glaucoma instead causes corneal cloudiness.");
add("mock-c-061","ch28-child-head","A 6-month-old has an asymmetric head shape. Palpation of the skull reveals a bony ridge along one suture line instead of a thin trough. Which condition is most likely?",
["Positional plagiocephaly","Cephalohematoma","Hydrocephalus","Craniosynostosis"],3,
["Positional plagiocephaly is flattening from lying on one side and is not marked by a bony ridge along a suture.","A cephalohematoma is a newborn scalp hemorrhage that resolves within weeks, not a ridge along a suture at 6 months.","Hydrocephalus presents with a bulging anterior fontanelle and possibly a setting sun sign.",""],
"Normal sutures feel like thin troughs; a bony ridge along a suture with an asymmetric head suggests craniosynostosis, premature closure of a suture. Positional plagiocephaly also causes asymmetry but from positioning, without a bony suture ridge.");
add("mock-c-062","ch28-child-murmur","A thriving 3-month-old has a soft systolic ejection murmur at the upper left sternal border that is also heard in both axillae and the back. There is no ejection click, S2 is normal, and the infant is not cyanotic. Which is the most likely explanation?",
["Pulmonary valve stenosis","Atrial septal defect","Peripheral pulmonary stenosis","Tetralogy of Fallot"],2,
["Pulmonary valve stenosis usually has a prominent early systolic ejection click, and P2 becomes delayed and softer.","An atrial septal defect murmur is usually not heard until after 1 year and comes with a widely split S2 in all phases of respiration.","","Tetralogy of Fallot causes variable cyanosis, and the pulmonary closure sound is usually not heard."],
"In some infants, a soft ejection murmur heard in the axilla and back indicates benign peripheral pulmonary stenosis, which usually disappears by age 1. Pulmonary valve stenosis is also at the upper left sternal border and can radiate to the lung fields, but it usually has a prominent ejection click.");
add("mock-c-063","ch28-child-resp","An infant with a cold has loud, harsh inspiratory sounds heard symmetrically over both sides of the chest. When the stethoscope is held just above the infant's mouth and nose, the sounds remain loud. What is the most likely source?",
["Transmitted upper airway sounds","Expiratory wheezing from asthma","Crackles from pneumonia","Unilateral lower airway obstruction"],0,
["","Wheezing is a musical expiratory sound from the lower airways, and these sounds are inspiratory.","Lower airway sounds such as crackles are often asymmetric and quieter above the mouth than over the chest.","Lower airway sounds are often asymmetric, while these sounds are symmetric and loud above the mouth."],
"Upper airway sounds are harsh, symmetric, almost always inspiratory, and remain loud when the stethoscope is held above the mouth; an upper respiratory infection commonly transmits them to the chest. Lower airway sounds are often asymmetric and quieter above the mouth.");
add("mock-c-064","ch29-preg-head","A patient at 22 weeks' gestation reports brief, sharp lower abdominal pain when standing up quickly or rolling over in bed. There is no bleeding, fluid leakage, or regular contraction pattern. Which explanation is most likely?",
["Braxton Hicks contractions","Onset of preterm labor","Constipation from slowed transit","Stretching of the round ligaments"],3,
["Braxton Hicks contractions are irregular uterine contractions described in the third trimester, not sharp positional pain.","Labor is suggested by contractions that become regular or painful, which are absent here.","Constipation is common in pregnancy but is not described as sharp pain triggered by movement or position change.",""],
"In the second trimester, rapid uterine growth stretches the round ligaments, producing sharp or cramping pain with movement or position change. Braxton Hicks contractions are a third-trimester phenomenon of irregular uterine contractions rather than positional pain.");
add("mock-c-065","ch29-preg-heart","A patient whose blood pressure was normal before pregnancy and at every prenatal visit through 20 weeks now has readings of 146/92 and 148/94 mm Hg on two visits at 28 weeks' gestation. Urine protein, platelets, and liver and kidney tests are normal, and there is no headache. Which classification fits?",
["Chronic hypertension","Preeclampsia","Gestational hypertension","Eclampsia"],2,
["Chronic hypertension is present before pregnancy or before 20 weeks, but this patient was normotensive until after 20 weeks.","Preeclampsia requires an additional feature such as proteinuria, thrombocytopenia, or organ dysfunction, none of which is present.","","Eclampsia is defined by new-onset seizures, which have not occurred."],
"Systolic pressure of at least 140 or diastolic of at least 90 mm Hg on two occasions after 20 weeks, without additional features, defines gestational hypertension. Preeclampsia would require at least one feature such as proteinuria, thrombocytopenia, renal or liver dysfunction, or new refractory headaches.");
add("mock-c-066","ch30-geriatric","During a medication review for an 80-year-old with several chronic conditions, the clinician wants to identify indicated preventive therapies that are missing from the regimen. Which tool is designed for this purpose?",
["Beers Criteria","STOPP criteria","Clinical decision support alerts","START criteria"],3,
["Beers Criteria identify drugs with a higher risk of adverse effects, not missing therapies.","STOPP criteria check for overmedication, inappropriate prescriptions, or harmful interactions.","Clinical decision support systems alert the clinician to potential interactions and dosing errors.",""],
"START criteria are used to find essential medications absent from the regimen, especially for prevention and chronic conditions. STOPP, its companion, addresses the opposite problem of inappropriate or redundant drugs already being taken.");
add("mock-c-067","ch30-geriatric","While fitting an older adult with a mobility aid, the examiner adjusts it so that there is a 1- to 2-inch gap between the top of the device and the patient's armpit. Which device is being fitted?",
["Standard cane","Crutches","Rollator","Quad cane"],1,
["The top of a cane should reach the wrist crease when the user stands upright.","","Walker and rollator handles are set to align with the user's wrist crease.","Canes, including a quad cane, are fitted so the top reaches the wrist crease."],
"Crutches are fitted with a 1- to 2-inch gap between their top and the armpit, with the handgrips at wrist crease height. Canes are fitted so their top reaches the wrist crease, and walker or rollator handles align with the wrist crease.");
add("mock-c-068","ch30-older-body","An asymptomatic 81-year-old living in the community has a systolic crescendo-decrescendo murmur in the second right interspace. Which interpretation is best supported?",
["Aortic sclerosis is more likely than aortic stenosis","Mitral valve prolapse is the most likely cause","Aortic stenosis is more likely than aortic sclerosis","The likely cause adds no cardiovascular risk"],0,
["","This murmur, systolic crescendo-decrescendo in the second right interspace, is attributed to aortic sclerosis or aortic stenosis, not mitral valve prolapse.","Aortic stenosis affects only 2% to 3% of community-dwelling older adults, versus up to 40% for aortic sclerosis.","Both aortic sclerosis and aortic stenosis are associated with increased cardiovascular disease and mortality."],
"A systolic crescendo-decrescendo murmur in the second right interspace suggests aortic sclerosis or aortic stenosis, and sclerosis is far more common (up to 40% versus 2% to 3%). Neither is benign in prognosis, since both carry increased cardiovascular risk and mortality.");
add("mock-c-069","ch11-delirium","A hospitalized patient has an acute change from baseline that fluctuates during the day, with rambling, illogical conversation. The patient is alert and repeats digit spans forward and backward without difficulty. Using the CAM algorithm, how should this be interpreted?",
["Delirium is confirmed by features 1 and 3","CAM is not met because inattention is absent","CAM is not met because consciousness is normal","Delirium is confirmed by any two CAM features"],1,
["Features 1 and 3 are not enough, because inattention (feature 2) is always required.","","Normal consciousness does not exclude delirium, because disorganized thinking can substitute for feature 4.","Not every pair qualifies; the CAM requires features 1 and 2 plus either 3 or 4."],
"The CAM requires an acute fluctuating change and inattention, plus either disorganized thinking or an altered level of consciousness. Without inattention, disorganized thinking alone cannot meet the algorithm.");
add("mock-c-070","ch11-delirium","A patient with known Alzheimer disease, previously stable, becomes lethargic and inattentive over one day while febrile with a urinary tract infection. Which explanation best fits?",
["Expected progression of Alzheimer disease","Progression to vascular dementia","Delirium superimposed on dementia","Onset of mild cognitive impairment"],2,
["Alzheimer disease progresses slowly over months to years, not over one day.","Vascular dementia is also a gradual dementia and does not explain an acute change with fever.","","Mild cognitive impairment is a milder state than the patient's existing dementia, not an acute change."],
"Acute onset, disturbed consciousness, inattention, and concurrent illness point to delirium, which may be superimposed on dementia. Alzheimer progression is slow and insidious, with attention usually preserved until late.");
root.L.ITEMS.forEach(function(it){if(it.id.indexOf('mock-c-')===0)it.pool='x';});
})(typeof window!=='undefined'?window:globalThis);
